'use strict';
const $=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeGiftLink(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&u.hostname&&!u.username&&!u.password&&!/[\u0000-\u001f\u007f]/.test(value)?u.href:'';}catch{return '';}}
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:n%100===0?0:2}).format(n/100);
const percent=(a,b)=>b?Math.max(0,Math.min(100,a/b*100)):0;
const storageKey='christmas-gift-studio-v1';
const PREVIEW_MODE=window.GIFT_STUDIO_CONFIG?.previewMode===true;
let previewUnlocked=false,authMode='signin',authPhase='loading',remoteError='';
let calculatorAmount='';
let policyView='';
let state,localError='',page='dashboard',search='',filter='all',categoryFilter='',sort='recipient',sb=null,user=null,revision=0,dirty=false,saving=false,conflict=false,remoteReady=false,saveTimer,toastTimer,deleteCategory='';
try{const raw=localStorage.getItem(storageKey);state=raw?Studio.validate(JSON.parse(raw)):Studio.example();}catch(e){state=Studio.fresh();localError='Local storage is unavailable or the saved planner is invalid. Export backups while we resolve it.';}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function status(message){$('#save-state').textContent=message;}
function persist(){if(!user&&!previewUnlocked)return;Studio.reconcileStockings(state);if(user){if(!remoteReady){toast('Wait for your account planner to load before editing.');return;}dirty=true;status('Changes waiting to save…');clearTimeout(saveTimer);saveTimer=setTimeout(saveRemote,500);}else{try{localStorage.setItem(storageKey,JSON.stringify(state));status('✓ Saved on this device only');}catch(e){localError='Not saved: device storage is unavailable or full. Download a backup.';status(localError);toast(localError);}}}
async function saveRemote(){if(!dirty||saving||conflict||!user||!remoteReady)return;saving=true;dirty=false;status('Saving to your account…');const snapshot=JSON.parse(JSON.stringify(state));try{const {data,error}=await sb.from('gift_studio_planners').update({payload:snapshot,revision:revision+1}).eq('user_id',user.id).eq('revision',revision).select('revision');if(error)throw error;if(!data?.length){conflict=true;dirty=true;throw Error('Another device changed this planner. Download a backup, then reload account data in Account & backups.');}revision=data[0].revision;status('✓ Saved to your account');}catch(e){dirty=true;status('Not synced — open Account & backups');toast(e.message);}finally{saving=false;if(dirty&&!conflict&&JSON.stringify(snapshot)!==JSON.stringify(state))setTimeout(saveRemote,500);}}
async function loadRemote(){remoteError='';remoteReady=false;status('Loading your account…');try{let {data,error}=await sb.from('gift_studio_planners').select('payload,revision').eq('user_id',user.id).maybeSingle();if(error)throw error;if(!data){const blank=Studio.fresh();blank.displayName=user.user_metadata?.display_name||'';const result=await sb.from('gift_studio_planners').insert({user_id:user.id,payload:blank,revision:1}).select('payload,revision').single();if(result.error)throw result.error;data=result.data;}state=Studio.validate(data.payload);revision=data.revision;conflict=false;dirty=false;remoteReady=true;status('✓ Saved to your account');render();}catch(e){remoteError=e.message;status('Account could not load — editing locked');render();}}
function sampleBanner(){return state.sample?`<div class="sample-banner"><span>✧ You’re exploring a filled-in example. All names and amounts are sample data.</span><button class="link-button" data-action="start">Start my planner</button></div>`:'';}
function header(title,subtitle){return `<div class="page-heading"><div><span class="eyebrow">CHRISTMAS ${state.year}</span><h1>${title}</h1><p>${subtitle}</p></div></div>`;}

function calculatorResult(remaining,raw){if(raw==='')return 'Enter a purchase total to see what would be left.';const amount=Number(raw);if(!Number.isFinite(amount)||amount<0||amount>1000000)return 'Enter an amount between $0 and $1,000,000.';const after=remaining-Math.round(amount*100);return after<0?`${money(-after)} over budget after this purchase`:`${money(after)} remaining after this purchase`;}
function calculatorMarkup(remaining){return `<details class="quick-calculator" ${calculatorAmount!==''?'open':''}><summary>Quick Calculator</summary><div class="calculator-content"><div class="calculator-heading"><h3>What if I spend…</h3><button type="button" class="calculator-clear" data-action="clear-calculator">Clear</button></div><label for="quick-purchase">Purchase total ($), including tax & shipping</label><input id="quick-purchase" type="number" min="0" max="1000000" step="0.01" inputmode="decimal" value="${esc(calculatorAmount)}" placeholder="e.g. 25.00" aria-describedby="calculator-note"><output id="calculator-result" aria-live="polite">${calculatorResult(remaining,calculatorAmount)}</output><p id="calculator-note">Preview only. For a purchase not yet marked Purchased.</p></div></details>`;}

function welcomeText(){const name=(state.displayName||user?.user_metadata?.display_name||user?.user_metadata?.full_name||'').trim();return name?'Welcome, '+esc(name):'Welcome!';}
function dashboard(){const t={...Studio.totals(state),...Studio.presentCounts(state)},d=Studio.days(state),done=t.bought&&t.wrapped===t.total;const season=percent(56-Math.max(0,d),56);return `${sampleBanner()}<section class="hero light-header"><div class="light-strand" aria-hidden="true"></div></section><div class="welcome"><div><h1 class="personal-welcome">${welcomeText()}</h1></div><div class="countdown"><span class="number">${Math.max(0,d)}</span><div><b>${d===0?'Merry Christmas!':d<0?'Christmas has passed':'sleeps until Christmas'}</b><small>December 25, ${state.year}</small><div class="countdown-progress" role="progressbar" aria-label="Christmas season countdown" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(season)}"><span style="width:${season}%"></span></div></div></div></div><section class="stats" aria-label="Holiday summary"><article class="card budget-card ${t.remaining<0?'over':''}"><span class="eyebrow">${t.remaining<0?'OVER YOUR BUDGET':'LEFT IN YOUR HOLIDAY BUDGET'}</span><div class="value">${money(Math.abs(t.remaining))}</div><small>${money(t.spent)} spent of ${money(state.budget)} · includes shipping</small><div class="progress"><span style="width:${percent(t.spent,state.budget)}%;background:#c1d0b3"></span></div><small>${t.afterPlan>=0?money(t.afterPlan)+' left after all listed gifts':money(-t.afterPlan)+' over budget if you buy every listed gift'}</small>${calculatorMarkup(t.remaining)}</article><article class="card"><div class="stat-top"><span class="eyebrow">PRESENTS PURCHASED</span><img class="dashboard-icon" src="assets/gift-icon.png" alt="" aria-hidden="true"></div><div class="stat-num">${t.bought} <small>of ${t.total} presents</small></div><div class="progress"><span style="width:${percent(t.bought,t.total)}%"></span></div><div class="stat-split"><span>${t.total-t.bought} presents to find</span><a href="#gifts" data-filter="buy">View gifts →</a></div></article><article class="card"><div class="stat-top"><span class="eyebrow">WRAPPED & ON THEIR WAY</span><img class="dashboard-icon" src="assets/stars-icon.png" alt="" aria-hidden="true"></div><div class="ready-numbers"><div><b>${t.wrapped}<small> / ${t.bought}</small></b><small>wrapped or shipped</small></div><div><b>${t.shipped}<small> / ${t.toShip}</small></b><small>shipped</small></div></div><div class="progress"><span style="width:${percent(t.wrapped,t.bought)}%;background:#ba7d79"></span></div><small>${done?'Everything is ready. Time for a little cocoa.':'A little ribbon, a little love.'}</small></article></section>${attention(t)}${stockingDashboard()}<div class="grid"><article class="card"><div class="section-head"><div><h2>Your giving budget</h2><p>Purchased spending by category · shipping included</p></div><a href="#setup" class="link-button">Edit budget</a></div>${state.categories.map((c,i)=>{const v=Studio.categoryTotals(state,c);return `<div class="budget-line"><div><span><i class="dot" style="background:${colors[i%colors.length]}"></i>${esc(c.name)}</span><b class="${v.spent>c.budget?'over-text':''}">${money(v.spent)} <small>/ ${money(c.budget)}</small></b></div><div class="progress"><span style="width:${percent(v.spent,c.budget)}%;background:${v.spent>c.budget?'#b45459':colors[i%colors.length]}"></span></div><small class="${v.planned>c.budget?'over-text':''}">${money(v.planned)} planned${v.planned>c.budget?' · '+money(v.planned-c.budget)+' above category budget':''}</small></div>`;}).join('')}<div class="legend"><span><i class="dot"></i>Bars show spent / category budget</span></div></article><article class="card"><div class="section-head"><div><h2>A little shopping left</h2><p>Recipients with gifts still to purchase</p></div><span class="badge">${Studio.groups(state,'buy').length} people</span></div><div class="list-scroll">${recipientList('buy')}</div></article><article class="card task-card"><div class="section-head"><div><h2>Wrap it with love</h2><p>Purchased gifts that need wrapping or shipping</p></div><span class="badge">${Studio.groups(state,'ready').length} people</span></div><div class="list-scroll">${recipientList('ready')}</div></article><article class="card"><div class="section-head"><div><h2>Little reminders</h2><p>Shipping plans, hiding spots, and holiday to-dos</p></div><span class="stat-icon">✶</span></div><textarea id="dashboard-notes" class="notes-field" rows="5" maxlength="10000" aria-label="Holiday reminders" placeholder="Pick up ribbon & tags…">${esc(state.notes)}</textarea><div class="info-strip">✧ ${t.unpriced?`${t.unpriced} gifts still need a price. Budget totals exclude those unknown amounts.`:'Gift and shipping costs are included in your totals.'}</div></article></div>`;}
const colors=['#829578','#ba7c78','#bc9b5f','#859da0','#a999ad','#9aab8d'];
function attention(t){const items=[];if(!state.budget)items.push('Set your overall budget in Setup to get started.');if(t.allocated!==state.budget)items.push(`Category budgets total ${money(t.allocated)} — ${money(Math.abs(state.budget-t.allocated))} ${t.allocated<state.budget?'still to allocate':'above your overall budget'}.`);const missing=state.gifts.filter(g=>g.purchased&&g.delivery==='shipped'&&g.status!=='shipped'&&!g.address.trim()).length;if(missing)items.push(`${missing} shipping ${missing===1?'gift needs':'gifts need'} an address.`);const today=new Date();const date=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;const late=state.gifts.filter(g=>!g.purchased&&g.buyBy&&g.buyBy<=date).length;if(late)items.push(`${late} unpurchased ${late===1?'gift has':'gifts have'} a buy-by date of today or earlier.`);return items.length?`<div class="callout">✦ ${items.map(esc).join(' &nbsp; · &nbsp; ')}</div>`:'';}

function statusLabel(status,type){if(type==='stocking')return status==='not wrapped'?'Not ready':status==='wrapped'?'Ready for stocking':status[0].toUpperCase()+status.slice(1);return status[0].toUpperCase()+status.slice(1);}
function statusOptions(g){return ['not wrapped',g.type==='stocking'?'ready for stocking':'wrapped',...(g.delivery==='shipped'?['shipped']:[])].map(v=>`<option value="${v}" ${g.status===v?'selected':''}>${statusLabel(v,g.type)}</option>`).join('');}
function stockingDashboard(){const groups=Studio.stockingGroups(state);return `<section class="card stocking-section"><div class="section-head"><div><h2>Stockings at a glance</h2><p>Little treats, big smiles. Stocking spending is already included in your giving budget.</p></div><button class="ghost small-button" data-action="add-stocking">＋ Add stocking stuffer</button></div>${groups.length?`<div class="stocking-grid">${groups.map(r=>`<article class="stocking-card"><div class="stocking-heading"><h3>${esc(r.name)}</h3><span class="badge ${r.stage==='Filled'?'stock-filled':''}">${r.stage}</span></div><p><b>${r.bought} of ${r.total}</b> items bought · ${r.ready} ready</p><div class="progress"><span style="width:${percent(r.bought,r.total)}%;background:#b77878"></span></div><div class="stock-money ${r.budget!==null&&r.spent>r.budget?'over-text':''}"><b>${money(r.spent)}</b>${r.budget!==null?' of '+money(r.budget):' spent · no stocking budget set'}</div><small class="${r.budget!==null&&r.planned>r.budget?'over-text':''}">${money(r.planned)} planned${r.budget!==null&&r.planned>r.budget?' · '+money(r.planned-r.budget)+' over stocking budget':''}</small>${r.total&&!r.canFill?'<small class="stock-hint">Buy every item and mark it ready before filling.</small>':''}<div class="actions"><button class="ghost small-button" data-stock-view="${esc(r.name)}">View items</button><button class="ghost small-button" data-stock-filled="${esc(r.name)}" ${!r.canFill?'disabled':''}>${r.stage==='Filled'?'Mark unfilled':'Mark filled'}</button></div></article>`).join('')}</div>`:'<div class="empty">Add a stocking stuffer to start a stocking for someone special.</div>'}</section>`;}
function stockingSetup(){const groups=Studio.stockingGroups(state),allocated=(state.stockings||[]).reduce((a,r)=>a+(r.budget??0),0),names=[...new Set([...state.gifts.map(g=>g.recipient),...groups.map(r=>r.name)])];return `<section class="card stocking-section"><div class="section-head"><div><h2>A little stocking budget</h2><p>Optional per-person limits. These are portions of your existing overall and category budgets, not extra spending allowances.</p></div></div><div class="callout ${allocated>state.budget?'error':'info'}">${money(allocated)} earmarked for stockings within your ${money(state.budget)} overall budget.${allocated>state.budget?' Stocking limits exceed your overall budget.':''} Gifts stay in their selected category and are counted only once.</div><div class="stock-budget-list">${groups.map(r=>`<div class="stock-budget-row"><div><b>${esc(r.name)}</b><small>${money(r.spent)} spent · ${money(r.planned)} planned</small></div><span>${r.budget===null?'No limit set':money(r.budget)+' budget'}</span><button type="button" class="ghost small-button" data-edit-stock="${esc(r.name)}" data-stock-budget="${r.budget===null?'':r.budget/100}">Edit</button>${state.stockings.some(x=>Studio.recipientKey(x.recipient)===Studio.recipientKey(r.name)&&x.budget!==null)?`<button class="icon-button" data-remove-stock="${esc(r.name)}" aria-label="Remove stocking budget for ${esc(r.name)}">×</button>`:''}</div>`).join('')}</div><form id="stock-budget-form" class="stock-budget-form"><label>Recipient<input name="recipient" required maxlength="100" list="stock-recipient-names" placeholder="e.g. Emma"><datalist id="stock-recipient-names">${names.map(n=>`<option value="${esc(n)}"></option>`).join('')}</datalist></label><label>Stocking budget ($)<input name="budget" type="number" min="0" max="1000000000" step="0.01" placeholder="Optional"></label><button class="primary" type="submit">Save stocking budget</button></form><p class="muted" style="margin-top:14px">Use the same recipient name as in the Gift Log. Name matching ignores capitalization and spaces at the ends.</p></section>`;}

function recipientList(type){const groups=Studio.groups(state,type);if(!groups.length)return `<div class="empty"><span>✧</span>${type==='buy'?'No gifts waiting to be purchased.':'No purchased gifts waiting to be wrapped or shipped.'}</div>`;return groups.map(r=>{const names=r.gifts.map(g=>g.name).join(', ');const wrap=r.gifts.filter(g=>g.type!=='stocking'&&g.status==='not wrapped').length,ship=r.gifts.filter(g=>g.delivery==='shipped'&&g.status!=='shipped').length;return `<div class="recipient-row"><span class="avatar">${esc(r.name[0]?.toUpperCase())}</span><div class="recipient-info"><b>${esc(r.name)}</b><small>${esc(names)}</small><small>${type==='buy'?`${r.gifts.length} to buy · ${money(r.gifts.reduce((a,g)=>a+Studio.cost(g),0))} planned`:[wrap?wrap+' to wrap':'',ship?ship+' to ship':''].filter(Boolean).join(' · ')}</small></div><button data-recipient="${esc(r.name)}" data-recipient-filter="${type==='buy'?'buy':'ready'}">View →</button></div>`;}).join('');}
function giftMatches(g){const hay=[g.recipient,g.name,g.notes].join(' ').toLowerCase();return hay.includes(search.toLowerCase())&&(!categoryFilter||g.category===categoryFilter)&&({all:true,buy:!g.purchased,ready:g.purchased&&((g.type!=='stocking'&&g.status==='not wrapped')||g.delivery==='shipped'&&g.status!=='shipped'),wrap:g.type!=='stocking'&&g.purchased&&g.status==='not wrapped',ship:g.purchased&&g.delivery==='shipped'&&g.status!=='shipped',stocking:g.type==='stocking'})[filter];}
function giftRows(){let gs=state.gifts.filter(giftMatches);gs.sort((a,b)=>sort==='cost'?Studio.cost(b)-Studio.cost(a):sort==='date'?(a.buyBy||'9999').localeCompare(b.buyBy||'9999'):a.recipient.localeCompare(b.recipient)||a.name.localeCompare(b.name));if(!gs.length)return '<div class="empty"><span>♧</span>No gifts here yet. Add a gift or change your filters.</div>';return `<table><thead><tr>${['Recipient','Category','Gift','Type','Cost + shipping','Purchased','Delivery','Status','Address','Links','Notes','Actions'].map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${gs.map(g=>`<tr><td data-label="Recipient"><span class="recipient">${esc(g.recipient)}</span></td><td data-label="Category">${esc(state.categories.find(c=>c.id===g.category)?.name)}</td><td data-label="Gift"><span class="gift-name">${esc(g.name)}</span><span class="sub">${g.type==='stocking'?'Stocking stuffer':''}${g.buyBy?' · Buy by '+esc(g.buyBy):''}</span></td><td data-label="Type"><span class="pill-status">${g.type==='stocking'?'Stocking stuffer':'Present'}</span></td><td data-label="Cost">${g.cost===null?'Not priced':money(g.cost)}${g.shipping?`<span class="sub">+ ${money(g.shipping)} shipping</span>`:''}</td><td data-label="Purchased"><input type="checkbox" data-purchase="${esc(g.id)}" aria-label="Mark ${esc(g.name)} for ${esc(g.recipient)} purchased" ${g.purchased?'checked':''}></td><td data-label="Delivery">${g.delivery==='shipped'?'Shipped':'In-person'}</td><td data-label="Status"><select data-status="${esc(g.id)}" aria-label="Status for ${esc(g.name)}" ${!g.purchased?'disabled':''}>${statusOptions(g)}</select></td><td data-label="Address"><span class="cell-note">${esc(g.address)||'—'}</span></td><td data-label="Links" class="link-cell">${safeGiftLink(g.link)?`<a href="${esc(safeGiftLink(g.link))}" target="_blank" rel="noopener noreferrer">Open link ↗</a>`:'—'}</td><td data-label="Notes"><span class="cell-note">${esc(g.notes)||'—'}</span></td><td data-label="Actions"><button class="ghost small-button" data-edit="${esc(g.id)}">Edit</button> <button class="icon-button" data-delete="${esc(g.id)}" aria-label="Delete ${esc(g.name)}">×</button></td></tr>`).join('')}</tbody></table>`;}
function giftPage(){return `${sampleBanner()}${header('The nice list','Every recipient, every present, every thoughtful detail.')}<div class="actions" style="margin-bottom:18px"><button class="primary" data-action="add">＋ Add a present</button><button class="ghost" data-action="add-stocking">＋ Add stocking stuffer</button></div><div class="toolbar"><input id="gift-search" aria-label="Search gifts" placeholder="Search recipients, gifts, notes…" value="${esc(search)}"><select id="category-filter" aria-label="Filter by category"><option value="">All categories</option>${state.categories.map(c=>`<option value="${esc(c.id)}" ${categoryFilter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select id="gift-sort" aria-label="Sort gifts"><option value="recipient" ${sort==='recipient'?'selected':''}>Sort: recipient</option><option value="cost" ${sort==='cost'?'selected':''}>Sort: highest cost</option><option value="date" ${sort==='date'?'selected':''}>Sort: buy-by date</option></select><button class="ghost" data-action="csv">Export CSV</button></div><div class="toolbar quick-filters">${[['all','All gifts'],['buy','To buy'],['wrap','To wrap'],['ship','To ship'],['stocking','Stocking stuffers']].map(([v,l])=>`<button data-gift-filter="${v}" class="${filter===v?'selected':''}">${l}</button>`).join('')}${filter==='ready'?'<button class="selected" data-gift-filter="ready">To wrap or ship</button>':''}<span id="filtered-count" class="muted"></span></div><div id="gift-table" class="table-wrap">${giftRows()}</div><div class="info-strip">Costs are per gift, including all units. A status can be updated after purchase. Stocking stuffers use “Ready for stocking” instead of wrapping. Marking an item unpurchased resets its status.</div>`;}
function setupPage(){const t=Studio.totals(state),diff=state.budget-t.allocated;return `${sampleBanner()}${header('Make room for the magic','Set your budget, choose your categories, and make this holiday yours.')}<div class="setup-grid"><div class="stack"><section class="card"><h2>Your holiday plan</h2><p class="muted">A comfortable budget is a lovely place to start.</p><form id="overall-form" class="stack"><label>Your name<input name="displayName" maxlength="100" autocomplete="given-name" value="${esc(state.displayName||'')}" placeholder="What should we call you?"></label><label>Overall budget ($)<input name="budget" type="number" min="0" max="1000000000" step="0.01" required value="${state.budget/100}"></label><label>Christmas year<input name="year" type="number" min="2020" max="2100" step="1" required value="${state.year}"></label><button class="primary" type="submit">Save holiday plan</button></form></section><section class="card"><h3>A note about your numbers</h3><p class="muted">Remaining budget subtracts purchased gifts and their shipping costs. Planned spending includes every gift you’ve listed, purchased or not.</p><p class="muted">Category budgets are optional. Leave them at zero if you only want an overall budget; the allocation reminder will stay visible.</p></section></div><section class="card"><div class="section-head"><div><h2>Giving categories</h2><p>Make a little space for everyone on your list.</p></div></div><form id="categories-form">${state.categories.map(c=>`<div class="category-row"><label>Category<input data-cat-name="${esc(c.id)}" required maxlength="100" value="${esc(c.name)}"></label><label>Budget ($)<input data-cat-budget="${esc(c.id)}" type="number" min="0" max="1000000000" step="0.01" required value="${c.budget/100}"></label><button type="button" class="icon-button" data-delete-category="${esc(c.id)}" aria-label="Delete ${esc(c.name)} category">×</button></div>`).join('')}<div class="allocation ${diff?'warn':''}"><b>${money(t.allocated)} allocated of ${money(state.budget)}</b><br>${diff===0?'✓ Your category budgets match your overall budget.':diff>0?money(diff)+' is still unallocated.':money(-diff)+' above your overall budget. Adjust categories or the overall budget.'}</div><div class="actions"><button type="button" class="ghost" data-action="add-category">＋ Add category</button><button class="primary" type="submit">Save categories</button></div><p class="muted" style="font-size:11px;margin-top:14px">Save category changes before leaving this page. Categories with gifts can be deleted after moving their gifts to another category.</p></form></section></div>${stockingSetup()}`;}

async function hashAccessCode(code){const bytes=new TextEncoder().encode(code.trim().toLowerCase());const digest=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');}
function authNotice(kind,title,message){const el=$('#auth-message');if(!el)return;el.className='auth-notice '+(kind==='success'?'auth-notice-success':'auth-notice-error');el.setAttribute('role',kind==='success'?'status':'alert');el.innerHTML=`<span class="auth-notice-icon" aria-hidden="true">${kind==='success'?'✓':'!'}</span><span><strong>${esc(title)}</strong><span>${esc(message)}</span></span>`;el.hidden=false;el.scrollIntoView({block:'nearest',behavior:'smooth'});}
function legalLinks(){return `<a href="#privacy" data-legal="privacy">Privacy Policy</a> · <a href="#terms" data-legal="terms">Terms of Use</a> · <a href="mailto:nichole@hihellodesign.com">Contact Support</a>`;}
function legalPage(){const privacy=policyView==='privacy';return `<section class="card legal-page"><button type="button" class="ghost" data-action="close-legal">← Back to planner</button>${privacy?`<h1>Privacy Policy</h1><p>Effective October 20, 2026 · Hi Hello Design Co.</p><h2>What we collect</h2><p>We use your email address, account details, and authentication information to provide account access. The gift planner saves information you enter, which may include recipient names, mailing addresses, gift ideas, links, notes, budgets, gift costs, and shipping costs.</p><h2>How we use it</h2><p>We use this information to authenticate you, save and display your planner, calculate spending totals, and provide support. This app does not connect to bank accounts or request payment card information.</p><h2>Storage and service providers</h2><p>Account authentication and cloud planner storage are provided through Supabase. Browser storage may also hold locally saved preview or planner information. Data is transmitted over encrypted HTTPS connections when the app is hosted securely. No internet service can guarantee absolute security.</p><h2>Retention and deletion</h2><p>Planner data is retained while your account is active. You can request permanent account and associated cloud planner deletion using the Delete My Account feature under Account & backups. Browser data and any backups you downloaded may remain on your devices until you delete them. Limited records may remain where required for legal, security, or operational purposes.</p><h2>Your choices</h2><p>You may download your planner backup, correct your entries, or delete your account. Contact us for privacy questions or assistance.</p><h2>Contact</h2><p>Hi Hello Design Co. · <a href="mailto:nichole@hihellodesign.com">nichole@hihellodesign.com</a></p>`:`<h1>Terms of Use</h1><p>Effective October 20, 2026 · Hi Hello Design Co.</p><h2>Purpose</h2><p>The Easy Holiday Gift Planner is a personal planning and budgeting tool. Its estimates and calculations are based on information you provide; they are not financial advice, bank records, or a guarantee of actual expenses. The app does not process purchases or connect to your financial accounts.</p><h2>Your account</h2><p>Provide accurate account information, keep your password private, and use your own authorized access code. Do not attempt to access another person's account or interfere with the service.</p><h2>Your data</h2><p>You control the gift and budget information you enter. You are responsible for keeping any downloaded backups secure and for verifying your entries and totals.</p><h2>Availability</h2><p>We work to keep the service available, but availability, uninterrupted access, and error-free calculations cannot be guaranteed. Keep a backup of information important to you.</p><h2>Support</h2><p>Questions about your account or this tool can be sent to <a href="mailto:nichole@hihellodesign.com">nichole@hihellodesign.com</a>.</p>`}</section>`;}
function authScreen(){const signup=authMode==='signup',ready=!!sb&&authPhase==='ready';return `<section class="auth-welcome"><div class="light-strand" aria-hidden="true"></div><div class="auth-brand"><span>✧</span><h1>The Easy Holiday<br>Gift Planner</h1><p>A little planning. A lot of Christmas magic.</p></div><div class="card auth-card"><div class="auth-tabs" aria-label="Account options"><button type="button" class="${signup?'':'selected'}" data-auth-mode="signin" aria-pressed="${!signup}">Sign in</button><button type="button" class="${signup?'selected':''}" data-auth-mode="signup" aria-pressed="${signup}">Create account</button></div><h2>${signup?'Create an Account':'Welcome back'}</h2><p class="muted">${signup?'Have your Etsy access PDF handy. Your access code is only needed when creating an account.':'Sign in to find your gifts, budgets, and holiday plans right where you left them.'}</p>${!ready?`<div class="callout info">${PREVIEW_MODE?'Design preview. Account registration is available on the connected live app.':authPhase==='loading'?'Connecting to your account…':'We can’t connect to the account service right now. Please try again shortly.'}</div>`:''}<form id="auth-form" class="auth-form">${signup?'<label>First name<input name="displayName" maxlength="100" autocomplete="given-name" required></label>':''}<label>Email<input type="email" name="email" autocomplete="email" required></label><label>Password<input type="password" name="password" autocomplete="${signup?'new-password':'current-password'}" ${signup?'minlength="8"':''} required></label>${signup?'<label>Access code<input type="password" name="accessCode" autocomplete="off" maxlength="128" required aria-describedby="access-code-help"><small id="access-code-help">You’ll find this in the PDF included with your Etsy purchase. Uppercase or lowercase both work.</small></label>':''}<button class="primary" type="submit" ${!ready?'disabled':''}>${signup?'Create my account':'Sign in'}</button>${!signup?'<button type="button" class="link-button" data-action="forgot">Forgot your password?</button>':''}<div id="auth-message" class="auth-notice" role="status" aria-live="polite" hidden></div></form>${PREVIEW_MODE?'<div class="auth-preview"><p>This preview uses fictional data and device storage.</p><button class="ghost" data-action="explore-preview">Explore the demo</button></div>':authPhase==='error'||authPhase==='unconfigured'?'<button class="ghost" data-action="reload-page">Reload page</button>':''}<div class="legal-links">${legalLinks()}</div></div></section>`;}

function accountPage(){return `${header('Your cozy little corner','Your account, saved plans, and a backup for peace of mind.')}<section class="card settings-card"><h2>${user?'Your account':sb?'Sign in to your planner':'Device preview'}</h2>${user?`<p>Signed in as <b class="account-label">${esc(user.email)}</b></p><p>Account data loads at sign-in and whenever you return to this tab, provided there are no unsaved edits. Avoid editing simultaneously on multiple devices.</p><div class="actions"><button class="ghost" data-action="retry-save">Retry saving</button><button class="ghost" data-action="reload-cloud">Reload account data</button><button class="ghost" data-action="signout">Sign out</button></div>`:`<p>This is your device preview. Sign in on the hosted planner to use your account.</p>`}</section><section class="card settings-card"><h2>A little backup, a lot of peace of mind</h2><p>Download a backup to keep a copy or move your planner. Restoring replaces the planner currently open${user?' in your account':' on this device'}.</p>${localError?`<p class="error">${esc(localError)}</p>`:''}<div class="actions"><button class="primary" data-action="backup">Download backup</button><button class="ghost" data-action="restore">Restore a backup</button></div></section><section class="card settings-card"><h2>A fresh beginning</h2><p>Clear the current planner to begin with the six default categories, or explore the example. Download a backup first if you want to keep your entries.</p><div class="actions"><button class="ghost" data-action="start">Start a blank planner</button><button class="ghost" data-action="sample">Load sample planner</button></div></section>${user?`<section class="card settings-card danger-zone"><h2>Delete your account</h2><p>Permanently delete your account and its saved cloud planner. This cannot be undone. Download a backup first if you want to keep your gifts and budgets.</p><button class="danger" data-action="delete-account">Delete My Account</button></section>`:''}`;}
function render(){if(policyView){document.body.classList.remove('auth-locked');$('#main').innerHTML=legalPage();return;}const locked=!user&&!previewUnlocked;document.body.classList.toggle('auth-locked',locked);if(locked){$('#main').innerHTML=authScreen();return;}page=['dashboard','gifts','setup','account'].includes(location.hash.slice(1))?location.hash.slice(1):'dashboard';document.body.dataset.page=page;$$('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#gift-count').textContent=state.gifts.length;$('#mode-pill').textContent=user?'Account planner':state.sample?'Sample · device preview':'Device preview';if(user&&!remoteReady){$('#main').innerHTML=remoteError?`<div class="card"><h2>Your planner could not load</h2><p>${esc(remoteError)}</p><p>Your saved account data has not been replaced.</p><button class="primary" data-action="reload-cloud">Retry loading</button> <button class="ghost" data-action="signout">Sign out</button></div>`:'<div class="card"><h2>Opening your holiday planner…</h2><p>Your saved gifts are on their way.</p></div>';return;}$('#main').innerHTML=({dashboard,gifts:giftPage,setup:setupPage,account:accountPage})[page]();if(!user)status(localError||'✓ Saved on this device only');if(page==='gifts')updateCount();}
function updateCount(){$('#filtered-count').textContent=state.gifts.filter(giftMatches).length+' gifts shown';}
function navigateGift(recipient='',f='all'){search=recipient;filter=f;categoryFilter='';if(location.hash==='#gifts')render();else location.hash='gifts';}
function openGift(id,type='gift'){if(!user&&!previewUnlocked)return;if(user&&!remoteReady)return toast('Your account planner is still loading.');const form=$('#gift-form');form.reset();form.elements.type.value=type;form.elements.status.innerHTML=statusOptions({type,delivery:'in-person',status:'not wrapped'});$('#gift-error').textContent='';form.elements.category.innerHTML=state.categories.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');const g=state.gifts.find(g=>g.id===id);$('#gift-title').textContent=g?'A thoughtful little edit':'Add a Gift';form.elements.id.value=g?.id||'';if(g){form.elements.type.value=g.type;form.elements.status.innerHTML=statusOptions(g);for(const key of ['recipient','category','name','delivery','status','address','link','notes','buyBy','type'])form.elements[key].value=g[key];form.elements.cost.value=g.cost===null?'':g.cost/100;form.elements.shipping.value=g.shipping/100;form.elements.purchased.checked=g.purchased;}updateGiftControls();$('#gift-dialog').showModal();}
function updateGiftControls(){const f=$('#gift-form'),p=f.elements.purchased.checked,type=f.elements.type.value,delivery=f.elements.delivery.value;let status=f.elements.status.value||'not wrapped';if(type==='stocking'&&status==='wrapped')status='ready for stocking';if(type==='gift'&&status==='ready for stocking')status='wrapped';if(!p)status='not wrapped';if(delivery!=='shipped'&&status==='shipped')status=type==='stocking'?'ready for stocking':'wrapped';f.elements.status.innerHTML=statusOptions({type,delivery,status});f.elements.status.disabled=!p;}

function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){download(`Easy-Holiday-Gift-Planner-${state.year}-backup.json`,JSON.stringify(state,null,2),'application/json');}
function csv(){const keys=['Recipient','Category','Gift','Cost','Shipping cost','Purchased','Delivery','Status','Address','Link','Notes','Buy by','Type'];const cell=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const lines=state.gifts.map(g=>[g.recipient,state.categories.find(c=>c.id===g.category)?.name,g.name,g.cost===null?'':(g.cost/100).toFixed(2),(g.shipping/100).toFixed(2),g.purchased?'Yes':'No',g.delivery,statusLabel(g.status,g.type),g.address,g.link,g.notes,g.buyBy,g.type]);download(`Easy-Holiday-Gift-Log-${state.year}.csv`,'\uFEFF'+[keys,...lines].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function removeCategory(id){if(state.categories.length===1)return toast('Keep at least one category.');const gifts=state.gifts.filter(g=>g.category===id);if(gifts.length){deleteCategory=id;$('#category-delete-message').textContent=`${gifts.length} gifts use this category. Choose their new category before deleting it.`;$('#category-reassign').innerHTML=state.categories.filter(c=>c.id!==id).map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');$('#category-dialog').showModal();}else if(confirm('Delete this category?')){state.categories=state.categories.filter(c=>c.id!==id);persist();render();}}
function captureCategories(){const cs=state.categories.map(c=>({...c,name:$(`[data-cat-name="${c.id}"]`).value.trim(),budget:Math.round(Number($(`[data-cat-budget="${c.id}"]`).value)*100)}));if(cs.some(c=>!c.name)||new Set(cs.map(c=>c.name.toLowerCase())).size!==cs.length)throw Error('Please give every category a different, nonempty name.');return cs;}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.legal){e.preventDefault();policyView=b.dataset.legal;render();window.scrollTo(0,0);return;}if(b.dataset.authMode){authMode=b.dataset.authMode;render();return;}if(b.hasAttribute('data-close')){b.closest('dialog').close();return;}if(b.dataset.editStock){const f=$('#stock-budget-form');f.elements.recipient.value=b.dataset.editStock;f.elements.budget.value=b.dataset.stockBudget;f.elements.budget.focus();return;}if(b.dataset.stockView){navigateGift(b.dataset.stockView,'stocking');return;}if(b.dataset.stockFilled){const r=Studio.stockingGroups(state).find(r=>Studio.recipientKey(r.name)===Studio.recipientKey(b.dataset.stockFilled));if(r?.canFill){let meta=state.stockings.find(x=>Studio.recipientKey(x.recipient)===Studio.recipientKey(r.name));if(!meta){meta={recipient:r.name,budget:null,filled:false};state.stockings.push(meta);}meta.filled=!meta.filled;persist();render();}return;}if(b.dataset.removeStock){if(confirm('Remove this stocking budget? Its gift entries will stay in the log.')){state.stockings=state.stockings.map(r=>Studio.recipientKey(r.recipient)===Studio.recipientKey(b.dataset.removeStock)?{...r,budget:null}:r).filter(r=>r.budget!==null||r.filled||state.gifts.some(g=>g.type==='stocking'&&Studio.recipientKey(g.recipient)===Studio.recipientKey(r.recipient)));persist();render();}return;}if(b.dataset.edit){openGift(b.dataset.edit);return;}if(b.dataset.delete){if(confirm('Remove this gift from your planner?')){state.gifts=state.gifts.filter(g=>g.id!==b.dataset.delete);persist();render();}return;}if(b.dataset.deleteCategory){try{if(!$('#categories-form').reportValidity())return;state.categories=captureCategories();removeCategory(b.dataset.deleteCategory);}catch(e){toast(e.message);}return;}if(b.dataset.recipient){navigateGift(b.dataset.recipient,b.dataset.recipientFilter);return;}if(b.dataset.giftFilter){filter=b.dataset.giftFilter;render();return;}if(b.dataset.filter){e.preventDefault();navigateGift('',b.dataset.filter);return;}try{switch(b.dataset.action){case'close-legal':policyView='';render();break;case'delete-account':await deleteAccount();break;case'explore-preview':if(PREVIEW_MODE){previewUnlocked=true;render();}break;case'reload-page':location.reload();break;case'clear-calculator':calculatorAmount='';$('#quick-purchase').value='';$('#calculator-result').textContent=calculatorResult(Studio.totals(state).remaining,'');$('#quick-purchase').focus();break;case'add':openGift();break;case'add-stocking':openGift(null,'stocking');break;case'csv':csv();break;case'backup':backup();break;case'restore':$('#restore-file').click();break;case'start':if(confirm('Start a blank planner? This replaces the current planner. Download a backup first to keep it.')){state=Studio.fresh(state.year);persist();render();}break;case'sample':if(confirm('Replace the current planner with fictional sample data? Download a backup first to keep your entries.')){state=Studio.example();persist();render();}break;case'add-category':if(!$('#categories-form').reportValidity())return;state.categories=captureCategories();if(state.categories.length>=100)return toast('You can have up to 100 categories.');let name='New category',n=2;while(state.categories.some(c=>c.name.toLowerCase()===name.toLowerCase()))name='New category '+n++;state.categories.push({id:Studio.id(),name,budget:0});persist();render();break;case'retry-save':await saveRemote();break;case'reload-cloud':if(!dirty||confirm('Reload saved account data? Unsaved edits on this device will be replaced. Download a backup first to keep them.'))await loadRemote();break;case'signout':if(dirty&&!confirm('Some edits have not synced. Sign out anyway? Download a backup first to keep those edits.'))return;clearTimeout(saveTimer);const logout=await sb.auth.signOut();if(logout.error)throw logout.error;break;case'forgot':{const email=$('#auth-form').elements.email.value;if(!sb)return toast('The account service is not connected in this preview.');if(!email||!$('#auth-form').elements.email.reportValidity())return toast('Enter your email address first.');const {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});if(error)throw error;authNotice('success','Check your inbox','If the account exists, a password-reset email will arrive shortly.');break;}}}catch(e){toast(e.message);}});
document.addEventListener('input',e=>{if(e.target.id==='quick-purchase'){calculatorAmount=e.target.value;$('#calculator-result').textContent=calculatorResult(Studio.totals(state).remaining,calculatorAmount);}if(e.target.id==='gift-search'){search=e.target.value;$('#gift-table').innerHTML=giftRows();updateCount();}if(e.target.id==='dashboard-notes'){state.notes=e.target.value;persist();}});
document.addEventListener('change',e=>{if(e.target.id==='category-filter'){categoryFilter=e.target.value;$('#gift-table').innerHTML=giftRows();updateCount();}if(e.target.id==='gift-sort'){sort=e.target.value;$('#gift-table').innerHTML=giftRows();}if(e.target.dataset.purchase){const g=state.gifts.find(g=>g.id===e.target.dataset.purchase);g.purchased=e.target.checked;if(!g.purchased)g.status='not wrapped';persist();render();}if(e.target.dataset.status){state.gifts.find(g=>g.id===e.target.dataset.status).status=e.target.value;persist();render();}if(e.target.closest('#gift-form')&&['purchased','delivery','type'].includes(e.target.name))updateGiftControls();});
$('#gift-form').addEventListener('submit',e=>{e.preventDefault();const f=e.target,v=new FormData(f);const g={id:v.get('id')||Studio.id(),recipient:v.get('recipient').trim(),category:v.get('category'),name:v.get('name').trim(),cost:v.get('cost')===''?null:Math.round(Number(v.get('cost'))*100),shipping:Math.round(Number(v.get('shipping')||0)*100),purchased:f.elements.purchased.checked,delivery:v.get('delivery'),status:f.elements.purchased.checked?f.elements.status.value:'not wrapped',address:v.get('address').trim(),link:v.get('link').trim(),notes:v.get('notes').trim(),buyBy:v.get('buyBy'),type:v.get('type')};try{Studio.validate({...state,gifts:[...state.gifts.filter(x=>x.id!==g.id),g]});const i=state.gifts.findIndex(x=>x.id===g.id);if(i<0)state.gifts.push(g);else state.gifts[i]=g;persist();$('#gift-dialog').close();render();toast('A little joy, saved.');}catch(err){$('#gift-error').textContent=err.message;}});
document.addEventListener('submit',async e=>{if(e.target.id==='stock-budget-form'){e.preventDefault();const f=e.target,recipient=f.elements.recipient.value.trim(),budget=f.elements.budget.value===''?null:Math.round(Number(f.elements.budget.value)*100);if(!recipient)return toast('Enter a recipient name.');const existing=state.stockings.find(r=>Studio.recipientKey(r.recipient)===Studio.recipientKey(recipient));if(existing)existing.budget=budget;else state.stockings.push({recipient,budget,filled:false});persist();render();toast('Stocking budget saved.');}if(e.target.id==='overall-form'){e.preventDefault();state.displayName=e.target.elements.displayName.value.trim();state.budget=Math.round(Number(e.target.elements.budget.value)*100);state.year=Number(e.target.elements.year.value);persist();render();toast('Holiday plan saved.');}if(e.target.id==='categories-form'){e.preventDefault();try{state.categories=captureCategories();persist();render();toast('Categories saved.');}catch(err){toast(err.message);}}if(e.target.id==='auth-form'){e.preventDefault();if(!sb)return;const form=e.target,buttons=[...form.querySelectorAll('button')];const notice=$('#auth-message');if(notice){notice.hidden=true;notice.textContent='';}buttons.forEach(b=>b.disabled=true);const submitButton=form.querySelector('button[type=submit]');if(submitButton)submitButton.textContent=authMode==='signup'?'Creating your account…':'Signing you in…';try{const credentials={email:form.elements.email.value.trim(),password:form.elements.password.value};let result;if(authMode==='signup'){const displayName=form.elements.displayName.value.trim();if(!displayName)throw Error('Enter your first name.');const code=form.elements.accessCode.value.trim();if(!code)throw Error('Enter the access code from your Etsy PDF.');const access_code_hash=await hashAccessCode(code);result=await sb.auth.signUp({...credentials,options:{emailRedirectTo:location.origin+location.pathname,data:{display_name:displayName,access_code_hash}}});form.elements.accessCode.value='';}else{result=await sb.auth.signInWithPassword(credentials);}if(result.error)throw result.error;if(!result.data.session){authNotice('success','Almost there! Check your email','We sent you a confirmation link. Open the email, confirm your account, then return here and sign in. Check your spam folder if you don’t see it.');form.elements.password.value='';}}catch(err){const msg=String(err?.message||'Please try again.');const invalidCode=/access.?code|invalid.?code|invite.?code|code.?invalid/i.test(msg);authNotice('error',invalidCode?'Incorrect access code':'We couldn’t create or access your account',invalidCode?'That access code doesn’t match. Double-check the code in your Etsy PDF and try again.':msg);}finally{buttons.forEach(b=>b.disabled=false);if(submitButton)submitButton.textContent=authMode==='signup'?'Create my account':'Sign in';}}});
$('#category-delete-form').addEventListener('submit',e=>{e.preventDefault();const target=$('#category-reassign').value;state.gifts.forEach(g=>{if(g.category===deleteCategory)g.category=target;});state.categories=state.categories.filter(c=>c.id!==deleteCategory);persist();$('#category-dialog').close();render();});
$('#restore-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10000000)throw Error('Please use a backup smaller than 10 MB.');const next=Studio.validate(JSON.parse(await file.text()));if(confirm('Replace your current planner with this backup?')){state=next;persist();render();toast('Backup restored.');}}catch(err){toast(err.message);}});
window.addEventListener('hashchange',()=>{render();$('#main').focus();});
window.addEventListener('beforeunload',e=>{if(user&&(dirty||saving)){e.preventDefault();e.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&user&&remoteReady&&!dirty&&!saving&&!$('#gift-dialog').open&&!$('#category-dialog').open&&page!=='setup')loadRemote();});
window.addEventListener('storage',e=>{if(e.key===storageKey&&!user){toast('Your planner changed in another tab. Reload to see those changes before editing.');}});
$('#password-form').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const {error}=await sb.auth.updateUser({password:e.target.elements.password.value});if(error)throw error;e.target.reset();$('#password-dialog').close();toast('Password updated.');}catch(err){$('#password-error').textContent=err.message;}finally{b.disabled=false;}});
async function deleteAccount(){if(!user||!sb)return;const email=user.email||'';const first=confirm('Delete your account and ALL saved cloud gift planner data permanently? This cannot be undone. Download a backup first if you want to keep your information.');if(!first)return;const typed=prompt('For your security, type DELETE to permanently delete your account:');if(typed!=='DELETE'){toast('Account deletion cancelled.');return;}const {data:{session},error}=await sb.auth.getSession();if(error||!session?.access_token)throw Error('Your session expired. Sign in again before deleting your account.');const response=await fetch('/.netlify/functions/delete-account',{method:'POST',headers:{'Authorization':'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({confirmation:'DELETE'})});const body=await response.json().catch(()=>({}));if(!response.ok)throw Error(body.error||'Deletion failed. Your account was not deleted. Contact support.');clearTimeout(saveTimer);dirty=false;remoteReady=false;user=null;previewUnlocked=false;policyView='';state=Studio.fresh();try{localStorage.removeItem(storageKey);}catch{}await sb.auth.signOut({scope:'local'}).catch(()=>{});authMode='signin';render();toast('Your account and saved cloud planner were deleted.');}
async function initialize(){render();const cfg=window.GIFT_STUDIO_CONFIG;if(!cfg?.supabaseUrl||!cfg?.supabasePublishableKey){authPhase='unconfigured';render();return;}status('Connecting to your account…');try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.57.4');sb=createClient(cfg.supabaseUrl,cfg.supabasePublishableKey);let initialized=false;let recovery=location.hash.includes('type=recovery');sb.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){recovery=true;setTimeout(()=>{if(!$('#password-dialog').open)$('#password-dialog').showModal();},0);return;}if(!initialized)return;if(event==='SIGNED_IN'&&session?.user.id!==user?.id){user=session.user;document.body.classList.remove('auth-locked');render();setTimeout(loadRemote,0);}if(event==='SIGNED_OUT'){user=null;previewUnlocked=false;authMode='signin';authPhase='ready';remoteReady=false;dirty=false;conflict=false;try{state=Studio.validate(JSON.parse(localStorage.getItem(storageKey)));}catch{state=Studio.fresh();}render();}});const {data,error}=await sb.auth.getSession();if(error)throw error;user=data.session?.user||null;if(user){document.body.classList.remove('auth-locked');await loadRemote();}else render();initialized=true;authPhase='ready';render();if(recovery&&user&&!$('#password-dialog').open)$('#password-dialog').showModal();}catch(e){authPhase='error';render();status('Account connection unavailable');toast('Unable to connect to your account. Please reload and try again.');}}
initialize();
